require_once __DIR__.'/auth/auth_check.php';require_role(valid_roles());ensure_clinical_tables();$id=(int)$_SESSION['user_id'];$errors=session_pull('errors',[]);$success=session_pull('success');$s=db()->prepare('SELECT u.fullname,u.email,u.phone,u.role,s.name AS specialization,u.qualification,h.name AS hospital_name,u.consultation_fee,u.bio,u.visiting_hours FROM users u LEFT JOIN specializations s ON s.id=u.specialization_id LEFT JOIN hospitals h ON h.id=u.hospital_id WHERE u.id=?');$s->execute([$id]);$user=$s->fetch();
?>
