 btn-solid-nhre">Update password</button></form></article></div><?php if($user['role']==='Doctor'):?><div class="col-12"><article class="dashboard-card"><h2 class="fs-5">Professional information</h2><p class="mb-1"><strong>Specialization:</strong> <?=e($user['specialization']?:'Not set')?></p><p class="mb-1"><strong>Qualification:</strong> <?=e($user['qualification']?:'Not set')?></p><p class="mb-1"><strong>Hospital:</strong> <?=e($user['hospital_name']?:'Not set')?></p><p class="mb-1"><strong>Consultation fee:</strong> <?=e($user['consultation_fee']?:'Not set')?></p><p class="mb-0"><strong>Visiting hours:</strong> <?=e($user['visiting_hours']?:'Not set')?></p><a class="btn btn-outline-nhre mt-3" href="profile.php">Update professional profile</a></article></div><?php endif;?></div></section></main><script src="assets/js/app.js?v=20260818-10"></script></body></html>
